import json,csv,pathlib,collections
OUT=pathlib.Path(__file__).resolve().parent
T=[]; I=[]; P=[]; C=[]
def talk(r,date,speaker,pages,title,kind,summary):
 T.append(dict(record=r,date=date,speaker=speaker,pages=pages,title=title,kind=kind,summary=summary))
def item(r,pages,kind,title,notes,statement,reconstruction='',cls='E',fate='',status='',literal='correct',match='partial',verification='read the result',development='none',problem='',worth='',refs=(),confidence='high',speaker=None):
 n=sum(x['record']==r for x in I)+1
 obj=dict(id=f'1966-{r}.{n}',record=r,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cls},fate=fate,present_status=status or r'As of 9 November 2026, this remains an established construction under the stated hypotheses.',literal_correctness=literal,publication_match=match,verification=verification,development=development,problem=problem,worth=worth,refs=list(refs),confidence=confidence)
 if speaker:obj['speaker']=speaker
 I.append(obj);return obj['id']
def correction(page,place,reads,should,evidence,applies='both',typ='faithful_error'):
 def esc(v):
  return v.replace('&',r'\&').replace('%',r'\%').replace('_',r'\_').replace('^',r'\textasciicircum{}')
 C.append(dict(page=page,place=esc(place),transcription_reads=esc(reads),should_read=esc(should),evidence=esc(evidence),applies_to=applies,type=typ))
def save():
 for name,obj in [('talks',T),('items',I),('problems',P)]:
  (OUT/(name+'.json')).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
 with (OUT/'corrections.csv').open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writeheader();w.writerows(C)

# Record 119: Kirillov's first Harish-Chandra lecture.
talk(119,'1967-02-13','A. A. Kirillov','P000187-P000191','Invariant eigendistributions and the first descent construction','talk',r'''The first lecture on Harish-Chandra begins after the programme on P000187. It states local integrability and regular-set analyticity for conjugation-invariant, centrally finite distributions, then sketches ellipticity, descent through centralizers, and reduction near the identity to the Lie algebra. Gelfand supplies explicit central operators for the general linear group. The lecture ends on P000191 before Dynin's heading. Several compressed proof steps need correction; the unexplained sentence about characters at infinity is retained as unidentified.''')
item(119,'P000187-P000188','theorem','Polynomial algebra of bi-invariant differential operators',r'''For a real semisimple group the notes identify the bi-invariant differential operators with a polynomial ring in \(\ell\) generators, where \(\ell\) is the rank; for \(SL(n)\), there is one generator in each degree \(2,\ldots,n\). Gelfand calls all these generators ``Laplace operators.''''',r'''For a connected real semisimple Lie group \(G\), the algebra of complex-valued differential operators invariant under left and right translations is \(Z(U(\mathfrak g_{\mathbb C}))\). The Harish-Chandra isomorphism identifies it with \(S(\mathfrak h_{\mathbb C})^W\), hence with a polynomial algebra on \(\operatorname{rank}_{\mathbb C}\mathfrak g_{\mathbb C}\) generators. For \(\mathfrak{sl}_n\), their orders are \(2,\ldots,n\).''',r'''Connectedness and complex coefficients are supplied. ``Rank'' is complex absolute rank, not real split rank. The historical name ``Laplace operator'' here includes higher-order central operators.''',fate=r'''The central-operator construction predates the lecture; see \citet[pp.~103--104]{gelfand1950center}.''',refs=['gelfand1950center'],match='partial')
item(119,'P000187','construction','Gelfand’s cyclic trace generators',r'''Gelfand writes \(E_{ij}f(x)=\frac d{dt}|_0f(x(1+te_{ij}))\), then \(\sum E_{ii}\), \(\sum E_{ik}E_{ki}\), and \(\sum E_{ij}E_{jk}E_{ki}\). He says subsequent expressions depend on the first \(n\) and refers to ``Gelfand, 1947.''''',r'''In \(U(\mathfrak{gl}_n(\mathbb C))\), set \(c_r=\sum_{i_1,\ldots,i_r}E_{i_1i_2}\cdots E_{i_ri_1}\). These central elements, for \(1\le r\le n\), generate the center. Passing to \(\mathfrak{sl}_n\) removes \(c_1\), leaving generators of degrees \(2,\ldots,n\).''',r'''The path \(1+te_{ii}\) is taken in \(GL_n\); the trace-free restriction gives the \(SL_n\) statement. Noncommuting factors are retained in their written cyclic order. The bibliographic date is not silently corrected to a first-circulation date.''',fate=r'''The matching paper appeared in 1950, received 3 July 1948: \citet[\S2, example~1, pp.~105--106; \S3, Theorem~2, p.~108]{gelfand1950center}.''',status=r'''As of 9 November 2026, the construction is classical. The notebook's 1947 reference remains a provenance discrepancy; earlier circulation has not been established.''',refs=['gelfand1950center'],match='exact',speaker='I. M. Gelfand')
item(119,'P000187-P000188','definition','Centrally finite invariant distributions',r'''The notes impose \(T^x=T\) and \(JT=0\), where \(R=\mathbb C[D_1,\ldots,D_\ell]\) and \(\dim R/J<\infty\); maximal ideals give ordinary joint eigenvalues, whereas \((D-\lambda)^2T=0\) illustrates a generalized eigencondition.''',r'''A distribution \(T\in\mathcal D'(G)\) is invariant and centrally finite if it is conjugation invariant and some finite-codimensional ideal \(J\subset Z(U(\mathfrak g_{\mathbb C}))\) annihilates it. For a maximal ideal \((D_i-\lambda_i)_i\), this is the joint eigendistribution condition. Finite codimension permits finite generalized joint eigenspaces; it does not require a maximal ideal.''',fate=r'''This is the finite-ideal framework of \citet[\S2, Lemma~1]{harishchandra1965algebra}; see also \citet[Definition~1.6.1]{galinalaurent2003characters}.''',refs=['harishchandra1965algebra','galinalaurent2003characters'],match='exact')
item(119,'P000188-P000189','theorem','Local integrability and regular-set analyticity',r'''Kirillov's main theorem says that a conjugation-invariant distribution annihilated by a finite-codimensional central ideal is locally summable; it is analytic at regular points but need not be continuous everywhere.''',r'''For a connected real reductive group in Harish-Chandra's setting, an invariant, centrally finite distribution on an invariant open set is represented by a locally integrable function. Its restriction to the regular semisimple set is real analytic. In particular, this applies to invariant eigendistributions and to distribution characters in the admissible irreducible setting. Analyticity is not asserted across the singular set.''',r'''The open set, the reductive setting, and ``regular semisimple'' are made explicit. The theorem is local; no assertion that all such distributions are characters, nor any classification of all unitary representations, follows.''',fate=r'''Already announced in 1963 and proved by 1965; \citet[Introduction; \S1.6]{galinalaurent2003characters} reviews the group theorem.''',status=r'''As of 9 November 2026, this is Harish-Chandra regularity, not an open problem. A later algebraic proof is given in \citet[Theorem~1.6.2, Corollary~1.6.3]{galinalaurent2003characters}.''',refs=['harishchandra1965group','galinalaurent2003characters'],match='exact',literal='correct with missing hypotheses')
item(119,'P000188','remark','Unidentified normalization of characters at infinity',r'''The sentence reads \ru{Характеры обращ. в 1 в $\infty$ --- м.б. разрывы}: characters become \(1\) at infinity and may have discontinuities. The scan supports the numeral \(1\) and the infinity sign.''',r'''No precise assertion can be recovered: neither a character class, a normalization, nor the meaning of the limiting regime is specified.''',r'''This is not replaced by a decay theorem or by the normalization of a spherical function at the identity.''',cls='F',fate=r'''Neither the group regularity theorem nor its modern restatement identifies this sentence; compare \citet[\S1.6]{galinalaurent2003characters}.''',status=r'''As of 9 November 2026, the intended normalization remains unidentified. There is no well-posed problem to develop.''',literal='not determinable',match='none found',verification='unresolved lead',refs=['galinalaurent2003characters'],confidence='low')
item(119,'P000188-P000189','method','Regular transverse sections and elliptic regularity',r'''The notes stratify conjugacy classes, choose a transverse \(\ell\)-dimensional section, assert that the radial operators have finite codimension in all differential operators, and write \(\Delta=\sum D_i^2\). After obtaining a polynomial in \(\Delta\) in \(J\), they conclude \(\Delta T=0\).''',r'''Near a regular semisimple element, conjugation invariance reduces the distribution to a Cartan slice. Its radial joint equations form an analytic elliptic system. Finite central codimension supplies polynomial annihilators for the generators. Combining equal-order powers of these annihilators with their formal adjoints gives an elliptic scalar consequence. The radial invariant polynomial algebra is a finite invariant subalgebra in the appropriate Cartan polynomial ring; it is not of finite vector-space codimension in the full algebra of differential operators.''',r'''The construction of an elliptic consequence repairs the sketch. With generators of unequal orders, the displayed sum of squares need not be elliptic in the ordinary single-order sense. The immediate conclusion from \(P(\Delta)\in J\) is \(P(\Delta)T=0\), not \(\Delta T=0\), unless the latter symbol has been renamed.''',fate=r'''The analytic regular-set step is in \citet[\S2, Lemma~1]{harishchandra1965algebra}.''',status=r'''As of 9 November 2026, the intended elliptic-system argument is established; the literal finite-codimension and scalar-operator shortcuts require emendation.''',literal='false as written',development='annotated',refs=['harishchandra1965algebra'],match='partial')
item(119,'P000189','method','Induction through semisimple centralizers and the Lie algebra',r'''The proof is divided into semisimple, ``nilpotent,'' and identity cases. A noncentral semisimple point descends to its smaller reductive centralizer; logarithm and exponential are used near the identity; the nilpotent case requires another argument.''',r'''Harish-Chandra descent reduces the local problem at a noncentral semisimple element to its reductive centralizer, of smaller semisimple dimension. Central elements are translated to the identity. A local analytic exponential comparison reduces the remaining group problem to the Lie algebra, where nilpotent orbits require a separate argument. In a linear algebraic group the group counterpart of a nilpotent Lie-algebra element is unipotent.''',r'''The comparison near the identity includes analytic density/conjugation factors and is not the bare substitution \(X\mapsto\exp X\) for every central differential operator. The three cases are a proof plan, not a disjoint exhaustive Jordan decomposition as literally listed.''',fate=r'''The 1965 proof explicitly uses centralizers and nilpotent analysis: \citet[Introduction]{harishchandra1965algebra}.''',refs=['harishchandra1965algebra'],match='partial',literal='correct with missing hypotheses')
item(119,'P000189-P000190','theorem','The conjugation map is a submersion on the descent domain',r'''For semisimple \(a\), the notes put \(\mathfrak z=\mathfrak g^a\), let \(\Xi\) be its connected subgroup, and define \(\varphi(x,y)=xayx^{-1}\), \(V_a(y)=\det(\operatorname{Ad}((ay)^{-1})-1)_{\mathfrak g/\mathfrak z}\), and \(\Xi'=\{V_a\ne0\}\). ``Theorem 1 (Lemma 14)'' says \(\operatorname{rank}d\varphi=\dim G\).''',r'''Let \(a\) be semisimple, \(\Xi=Z_G(a)^0\), and \(\Xi'\) the indicated open subset. Then \(\varphi:G\times\Xi'\to G\) is a smooth analytic submersion. In tangent coordinates at \((1,y)\), obtained by right multiplication \(y\exp(tZ)\) and left trivialization at \(ay\), \[d\varphi(X,Z)=(\operatorname{Ad}((ay)^{-1})-1)X+Z.\] Invertibility on \(\mathfrak g/\mathfrak z\) and the \(Z\)-term prove surjectivity.''',r'''The determinant is a function, not an assertion of nonvanishing for every \(y\in\Xi\); it is nonzero at \(y=1\), so the useful neighborhood is nonempty. This is a submersion, not a globally unique representative of each conjugacy class.''',fate=r'''This belongs to the 1965 group descent proof, \citet[pp.~457--508]{harishchandra1965group}; the notebook's Lemma~14 number was not independently verified.''',refs=['harishchandra1965group'],match='partial',verification='publisher metadata checked')
item(119,'P000190-P000191','construction','Fiber integration and distributional pullback under a submersion',r'''For a submersion \(\pi:M\to N\) and smooth volume measures, \(\alpha\in C_c^\infty(M)\) is sent to \(f_\alpha\in C_c^\infty(N)\) by \(\int_M\alpha(F\circ\pi)d\mu=\int_NFf_\alpha d\nu\). The verbal phrase says generalized functions move ``from \(M\) to \(N\).'' The next lecture corrects the direction in a diagram.''',r'''With positive smooth densities fixed, fiber integration defines a continuous map \(\pi_!:C_c^\infty(M)\to C_c^\infty(N)\). Its transpose defines the pullback \(\pi^*:\mathcal D'(N)\to\mathcal D'(M)\), with \(\langle\pi^*T,\alpha\rangle=\langle T,\pi_!\alpha\rangle\). No properness is needed for compactly supported test functions; pushing arbitrary distributions forward would require an additional support/properness condition.''',r'''The map is phrased in densities to avoid orientation assumptions. The verbal direction of transfer is separated from the displayed, correct test-function formula.''',fate=r'''A standard distributional ingredient of the descent reviewed in \citet[Introduction; \S1.6]{galinalaurent2003characters}; the notebook itself gives its local product proof.''',literal='correct with missing hypotheses',refs=['galinalaurent2003characters'],match='partial')
item(119,'P000191','definition','Mixed differential notation for conjugation',r'''Kirillov writes \(f(x;D_1:y;D_2)\) for differentiation in both variables and uses \(f(x:y)=f(xyx^{-1})\), omitting identity operators.''',r'''For a smooth function \(f\) on \(G\), put \(F(x,y)=f(xyx^{-1})\). Then \(f(x;D_1:y;D_2)=(D_{1,x}D_{2,y}F)(x,y)\), with the order and left/right invariant conventions fixed consistently. This notation introduces the bilinear operator \(\Gamma_y\) in record 121.''',fate=r'''Expository notation for the group proof cited as \citet{harishchandra1965group}; no independent theorem is asserted.''',refs=['harishchandra1965group'],verification='publisher metadata checked',match='partial')
correction('P000187','Gelfand reference beneath cyclic operators','see Gelfand, 1947','Keep 1947 diplomatically; identify the matching published paper as Gelfand 1950, received 3 July 1948.','The scan has 1947. Math-Net and the opened original paper establish publication and receipt dates, but do not rule out earlier circulation.','both','provenance')
correction('P000188','characters at infinity','Characters become 1 at infinity','No emendation supported; retain as unidentified.','Scan inspection confirms the compressed wording, the numeral 1, and the infinity sign. Neither the character normalization nor the limiting variable is stated.','both','ambiguity')
correction('P000189','radial operator algebra','finite codimension in the ring of all differential operators','Finite-module/invariant-polynomial statement on a Cartan slice; not finite vector-space codimension in all differential operators.','The same assertion is visible in the scan. Arbitrary variable coefficients and arbitrary orders preclude the literal finite-codimension assertion.','both','faithful_error')
correction('P000189','elliptic sum and annihilator','Delta=sum D_i^2 is elliptic; P(Delta) is in J; thus Delta T=0','Use an elliptic consequence of the full joint system; conclude P(Delta)T=0, or explicitly rename P(Delta).','The scan repeats the same Delta. Unequal generator orders make the displayed sum-of-squares ellipticity claim insufficient.','both','faithful_error')
correction('P000189','three cases for group elements','nilpotent group element','Unipotent group element, or nilpotent element after passage to the Lie algebra.','The scan says nilpotent; this is a terminology emendation, not a transcription correction.','both','faithful_error')
correction('P000190','direction of transfer','generalized functions from M to N','Test functions are integrated from M to N; dual distributions pull back from N to M.','The defining integral and the explicit reverse distribution arrow on P000196 determine the direction.','both','faithful_error')
save()

# Record 120: Dynin.
talk(120,'1967-02-13','A. S. Dynin','P000191-P000192','Pseudodifferential operators on bundles and the de Rham example','talk',r'''Dynin begins after Kirillov on P000191, globalizing pseudodifferential operators by coordinate cutoffs and the off-diagonal smoothing condition. The only worked example is the operator \(d+d^*\), its Laplacian, and the Hodge identification with de Rham cohomology. The final timetable is administrative, not another mathematical result.''')
item(120,'P000191','definition','Pseudodifferential operators between vector bundles',r'''For compact smooth \(X\) and bundles \(E_1,E_2\), locally cut off operators \(\psi_iA\varphi_i\) must be ordinary matrix pseudodifferential operators; if \(\varphi\psi=0\), \(\psi A\varphi\) is smoothing.''',r'''For smooth finite-rank complex bundles on a closed smooth manifold, a continuous linear map on smooth sections is a pseudodifferential operator of order \(m\) if its localized expressions lie in the prescribed coordinate symbol class and its Schwartz kernel is smooth off the diagonal. Cutoffs with disjoint supports give smoothing compositions. The stated pointwise condition \(\varphi\psi=0\) also suffices for finite-order pseudodifferential kernels: the product \(\psi(x)\varphi(y)\) is flat along the diagonal where the supports touch.''',r'''The symbol class, order, and continuity are supplied. Pointwise zero product is not erroneously replaced by a supposedly necessary positive separation of supports.''',fate=r'''Dynin's prelecture exposition gives this localization: \citet[\S1.2]{dynin1966index}, submitted March 1965, published 1966.''',refs=['dynin1966index'],literal='correct with missing hypotheses',match='exact')
item(120,'P000192','construction','The Hodge–de Rham operator and its square',r'''The notes use all inhomogeneous differential forms, set \(\delta=d^*\), call \(d+\delta\) a Cauchy--Riemann operator, and identify \((d+\delta)^2\) with the Laplacian.''',r'''On a closed Riemannian manifold \(X\), \(D=d+d^*\) acts on \(\Omega^*(X;\mathbb C)\), exchanges even and odd forms, and satisfies \(D^2=dd^*+d^*d=\Delta\), the Hodge Laplacian, which preserves form degree. The bundles are \(\Lambda^*T^*X\otimes\mathbb C\); a metric can identify tangent and cotangent bundles.''',r'''The modern name is the Hodge--de Rham Dirac operator. The notebook's use of \(\Lambda TX\) is interpreted via the metric rather than as the natural bundle of differential forms.''',fate=r'''Already in \citet[\S1.3, example~7]{dynin1966index}.''',refs=['dynin1966index'],match='exact',literal='correct with missing hypotheses')
item(120,'P000192','theorem','Harmonic representatives for de Rham cohomology',r'''Hodge's theorem is written \(\ker\Delta|_{\Lambda^kT(X)}=H^k(X,\mathbb C)\); a heat-equation proof is attributed informally to ``Moren.''''',r'''For a closed smooth Riemannian manifold, the map from harmonic complex \(k\)-forms to their de Rham classes is an isomorphism \(\mathcal H^k(X)\simeq H^k_{\mathrm{dR}}(X;\mathbb C)\). Every cohomology class has a unique harmonic representative. A manifold with boundary requires appropriate absolute or relative boundary conditions and a corresponding cohomology theory.''',r'''The equality is a canonical isomorphism, not equality of sets. No specific Moren/Maurin book or heat proof is identified from the surname alone.''',fate=r'''The Hodge example is used in \citet[\S1.3, examples~7--8]{dynin1966index}.''',refs=['dynin1966index'],match='exact',literal='correct with missing hypotheses')
correction('P000192','bundle of differential forms','Lambda T(X)','Lambda T^*(X), or explicitly use the Riemannian metric to identify it with Lambda T(X).','The scan and transcription omit the dual; the exterior differential naturally acts on covariant differential forms.','both','faithful_error')
correction('P000192','name of d+delta','Cauchy–Riemann operator','Hodge–de Rham operator (historical terminology retained in notes).','The displayed square and all-degree form domain identify d+d^*. The name in the scan is faithfully translated.','both','ambiguity')
save()

# Record 121: the radial operator.
talk(121,'1967-02-20','A. A. Kirillov','P000193-P000195','Enveloping-algebra construction of radial differential operators','talk',r'''The second Harish-Chandra lecture constructs \(\Gamma_y\), transferring differentiation in the conjugating variable to the section. Its associated-graded calculation yields a PBW decomposition and the constant transverse term defining the radial operator. The first part of P000195 still belongs to this lecture; the dated 27 February heading starts record 122.''')
item(121,'P000193','construction','Local centralizer slice and pointwise enveloping-algebra description',r'''A semisimple \(a\) is fixed; the connected centralizer is called a section meeting every conjugacy class once. The notes write \(\mathfrak z=\{X:\operatorname{ad}_aX=X\}\) and \(D_y\in\mathfrak g\) for the left-invariant operator agreeing with a differential operator \(D\) at \(y\).''',r'''Use \(\mathfrak z=\ker(\operatorname{Ad}(a)-1)\). Left trivialization identifies the value of an order-\(m\) differential operator at \(y\) with an element \(D_y\in U_{\le m}(\mathfrak g_{\mathbb C})\); smoothly varying \(D_y\) describes \(D\). The centralizer provides a redundant local descent submanifold on the regularity domain, not a global one-point-per-orbit cross-section.''',r'''Here \(\operatorname{Ad}\), rather than the Lie-algebra map \(\operatorname{ad}\), acts because \(a\in G\). The notation \(\mathfrak g\) for the enveloping algebra is explicitly clarified on P000194. Weyl-group ambiguity survives on a Cartan section.''',fate=r'''This is the classical descent framework of \citet{harishchandra1965group}; the exact source lemma was not read.''',refs=['harishchandra1965group'],verification='publisher metadata checked',literal='correct with missing hypotheses')
item(121,'P000193-P000194','construction','The representation sigma and the transfer operator Gamma',r'''The formula is \(\Gamma_y(u\otimes v)=\sigma_y(u)v\), with \(\sigma_y(X)v=\operatorname{Ad}(y^{-1})X\,v-vX\). It is used to replace operators in the two variables of \(f(xyx^{-1})\) by one operator in \(y\).''',r'''For fixed \(y\in G\), the map \(X\mapsto L_{\operatorname{Ad}(y^{-1})X}-R_X\) is a Lie-algebra representation on \(U(\mathfrak g_{\mathbb C})\), hence extends to its enveloping algebra. Define the bilinear transfer \(\Gamma_y(u\otimes v)=\sigma_y(u)v\). With the notebook's invariant differentiation convention it encodes \(f(x;u:y;v)=f(x:y;\Gamma_y(u\otimes v))\).''',r'''The left and right multiplications act on the enveloping algebra. Their commutators have opposite signs, which is essential to the representation identity. For descent at \(ay\), use \(\Gamma_{ay}\).''',fate=r'''The construction is expository Harish-Chandra descent, \citet{harishchandra1965group}; publication matching of this formula is partial.''',refs=['harishchandra1965group'],verification='publisher metadata checked')
item(121,'P000194','theorem','PBW leading term and the transverse decomposition',r'''The leading term of \(\Gamma_y(X_1\cdots X_r\otimes Y_1\cdots Y_s)\) is the product of \(X'_i=(\operatorname{Ad}(y^{-1})-1)X_i\) and the \(Y_j\). A complement \(\mathfrak g=\mathfrak z+\mathfrak q\), stable under \(\mathfrak z\), is introduced, and \(\Gamma_y\) is declared an isomorphism on the corresponding generated spaces.''',r'''Choose an \(\operatorname{Ad}(a)\)-stable complement \(\mathfrak q\) to \(\mathfrak z\), also stable under the connected centralizer. Identify \(S(\mathfrak q)\) with its symmetrized PBW subspace in \(U(\mathfrak g_{\mathbb C})\). For \(y\in\Xi'\), \[\Gamma_{ay}:S(\mathfrak q_{\mathbb C})\otimes U(\mathfrak z_{\mathbb C})\longrightarrow U(\mathfrak g_{\mathbb C})\] is a filtered vector-space isomorphism: its associated graded is multiplication after the invertible transformation \((\operatorname{Ad}((ay)^{-1})-1)|_{\mathfrak q}\).''',r'''The space generated by \(\mathfrak q\) must mean the PBW symmetric subspace, not the associative subalgebra: \(\mathfrak q\) need not be a Lie subalgebra. The displayed leading-term equality holds modulo lower filtration. If \(X\) commutes with \(y\), this leading term vanishes, whereas \(\sigma_y(X)=[X,\cdot]\) need not vanish.''',fate=r'''This is the filtered-algebra mechanism of the cited 1965 descent construction, \citet{harishchandra1965group}.''',refs=['harishchandra1965group'],verification='publisher metadata checked',literal='correct with missing hypotheses',development='annotated')
item(121,'P000194-P000195','construction','Radial part as the constant transverse coefficient',r'''On \(a\Xi\), \(\Delta=\delta_{a,G/\Xi}(D)\) is defined by \(\Delta_{ay}=\alpha(D_{ay})\), where \(D-\alpha(D)\) belongs to \(\Gamma_y(\mathfrak q^+\otimes\mathfrak z)\). It is said to act identically on orbit-constant functions.''',r'''On \(a\Xi'\), expand \(D_{ay}\) through the PBW isomorphism of the preceding item and project to the degree-zero \(S(\mathfrak q)\) component. The resulting smooth \(U(\mathfrak z)\)-valued coefficients define the radial operator \(\delta_a(D)\). For a locally conjugation-invariant smooth \(f\), \[(Df)|_{a\Xi'}=\delta_a(D)(f|_{a\Xi'}).\]''',r'''The omitted enveloping/symmetric-algebra notation and \(ay\)-dependence are restored. The result concerns invariant functions on the descent domain; it is not restriction of an arbitrary differential operator on arbitrary functions to an arbitrary submanifold.''',fate=r'''A classical radial-part construction, \citet{harishchandra1965group}; exact group-paper formula verification remains metadata-level.''',refs=['harishchandra1965group'],verification='publisher metadata checked',literal='correct with missing hypotheses')
correction('P000193','centralizer definition','ad_a X=X','Ad(a)X=X for a group element a.','The scan has the lower-case notation. The earlier page explicitly defines Ad_a(z)=aza^{-1}.','both','faithful_error')
correction('P000193','section through conjugacy classes','section meeting each conjugacy class in one element','A local centralizer descent submanifold, generally redundant; uniqueness requires an additional local quotient and fails globally.','The wording is in the scan. The submersion construction and ordinary Weyl conjugacy demonstrate the omitted qualification.','both','faithful_error')
correction('P000193-P000194','pointwise operator and generated transverse space','D_y in g; q and z generate subalgebras of the enveloping algebra','D_y in U(g); use the symmetrized PBW space S(q) and U(z).','P000194 itself labels g as the enveloping algebra. An arbitrary invariant complement q is not a Lie subalgebra, so its associative generated algebra cannot serve as the stated PBW factor.','both','ambiguity')
save()

# Record 122: distributional descent.
talk(122,'1967-02-27','A. A. Kirillov','P000195-P000197','Distributional descent and the induction step for regularity','talk',r'''The third lecture returns to continuous fiber integration, pulls an invariant distribution back to \(G\times\Xi'\), and factors it as Haar measure times a distribution on the centralizer. It states intertwining with radial differential operators and finite central codimension, thereby reducing local integrability to a smaller group. The notebook itself rejects an attempted explicit inverse-substitution formula.''')
item(122,'P000195-P000196','theorem','Continuity of fiber integration',r'''The existence and continuity of \(\alpha\mapsto f_\alpha\) are stated in the usual compactly supported smooth topologies. The first line mistakenly repeats \(C_c^\infty(M)\) as the target; the product case integrates over the extra variable.''',r'''For a smooth submersion \(\pi:M\to N\) and smooth positive densities, fiber integration is continuous \(\pi_!:C_c^\infty(M)\to C_c^\infty(N)\) in the standard LF test-function topology. On a product with product density it is \((\pi_!\alpha)(y)=\int_P\alpha(y,z)\,dz\); coordinate products and a partition of unity give the general map.''',r'''The target is \(N\), as the displayed identity and variable \(y\) already require. This repeats and proves the construction at 1966-119.9 rather than introducing a new research question.''',fate=r'''The notebook's local product argument establishes the standard construction used in \citet{harishchandra1965group}.''',refs=['harishchandra1965group'],verification='publisher metadata checked',literal='false as written',match='partial')
item(122,'P000196','theorem','Translation-invariant distributions are Haar measures',r'''A lemma says that a generalized function invariant under translations is integration against Haar measure, up to a constant.''',r'''On a connected Lie group \(G\), a left-translation-invariant distribution is a constant multiple of left Haar measure. More generally, a distribution on \(G\times V\) invariant under translations of the first factor is uniquely \(dg\otimes S\), with \(S\in\mathcal D'(V)\).''',r'''The product form is the parameter version needed below. For reductive \(G\), unimodularity removes a left/right Haar distinction; the formulation still specifies left invariance.''',fate=r'''An elementary, preexisting ingredient of the descent exposition \citep{harishchandra1965group}.''',refs=['harishchandra1965group'],verification='publisher metadata checked',match='partial')
item(122,'P000195-P000196','construction','The descended distribution sigma_T',r'''Pulling \(T\) back through \(\varphi(x,y)=xayx^{-1}\) gives \(T'\), translation invariant in the first variable; hence \(T'=1\otimes\sigma_T\).''',r'''For invariant \(T\) on the open image of the descent submersion, \(\varphi^*T\) is invariant under left translations of its first factor. Fix Haar density \(dg\); then a unique \(\sigma_T\in\mathcal D'(\Xi')\) satisfies \(\varphi^*T=dg\otimes\sigma_T\), under the chosen product-density convention. For \(\gamma\in C_c^\infty(G)\) with \(\int\gamma dg=1\), \[\langle\sigma_T,\beta\rangle=\langle T,\varphi_!(\gamma\otimes\beta)\rangle.\]''',r'''The final formula is the valid fiber-integration interpretation, not a literal substitution of \(a^{-1}z^{-1}xz\) into a function defined only on the centralizer.''',fate=r'''Classical Harish-Chandra descent, with the group-paper bibliographic identification \citep{harishchandra1965group}.''',refs=['harishchandra1965group'],verification='publisher metadata checked',match='partial')
item(122,'P000196','claim','The rejected explicit formula for descent',r'''The notebook proposes \(\langle\sigma_T,\beta\rangle=\langle T,\int_G\gamma(z)\beta(a^{-1}z^{-1}xz)dz\rangle\), then adds \ru{Она не имеет смысла} (``It has no meaning''). A diagonal dashed line crosses the formula region.''',r'''As written, the formula is undefined: \(\beta\) is a test function on \(\Xi\), but \(a^{-1}z^{-1}xz\) is generally not in \(\Xi\). Arbitrary extensions of \(\beta\) do not repair it canonically. The correct test function on \(G\) is \(\varphi_!(\gamma\otimes\beta)\), defined by integration along fibers and its Jacobian, as in the preceding item.''',r'''The notebook's own objection is preserved. The diagonal line's function as cancellation or connector remains uncertain; the mathematical type mismatch does not depend on that palaeographic choice.''',fate=r'''An abandoned formula inside an established descent construction \citep{harishchandra1965group}; it is not an unsolved theorem.''',status=r'''As of 9 November 2026, the literal formula is invalid. The fiber-integral definition supplies the established replacement.''',refs=['harishchandra1965group'],literal='false as written',verification='publisher metadata checked',development='annotated')
item(122,'P000197','theorem','Intertwining radial operators with descended distributions',r'''The lemma is \(\sigma_{DT}=\Delta\sigma_T\), with \(\Delta=\delta_{a,G/\Xi}(D)\); the notes emphasize the use of \(\Gamma_{ay}\).''',r'''For an invariant differential operator \(D\), Harish-Chandra descent intertwines its action on invariant distributions with the corresponding radial operator on the centralizer. If distributions are defined by duality using densities, the radial operator on distributions must be defined with the compatible formal transpose and density conjugation. With those conventions, \(\sigma_{DT}=\delta_a(D)\sigma_T\).''',r'''The smooth-function radial identity alone does not justify using the same coefficient expression on distributions with arbitrary densities. The compatible transpose convention is an essential supplied hypothesis.''',fate=r'''The identity belongs to the cited 1965 group descent argument \citep{harishchandra1965group}; its exact printed lemma was not verified.''',refs=['harishchandra1965group'],literal='correct with missing hypotheses',verification='publisher metadata checked')
item(122,'P000197','theorem','Finite central codimension survives descent',r'''The notes say the central operators' images generate an ideal of finite codimension in \(Z(U(\mathfrak z))\), and display an ideal mapping from \(Z(U(\mathfrak g))\) to \(Z(U(\mathfrak z))\).''',r'''After the appropriate Harish-Chandra radial conjugation, the centralizer homomorphism identifies the relevant centers with \(S(\mathfrak h)^W\subset S(\mathfrak h)^{W_{\mathfrak z}}\). This is a finite extension. Consequently, if \(J\subset Z(U(\mathfrak g))\) has finite codimension, its extended ideal in \(Z(U(\mathfrak z))\) has finite codimension and annihilates the descended distribution.''',r'''It is the image of the annihilating ideal, not the entire center, whose extension matters; the entire unital center already contains \(1\). The displayed raw radial operator includes conjugations not recorded in the notebook's schematic center diagram.''',fate=r'''This is the finite-invariant-algebra step in classical descent \citep{harishchandra1965group}.''',refs=['harishchandra1965group'],literal='correct with missing hypotheses',verification='publisher metadata checked',development='annotated')
item(122,'P000197','method','Recovering local integrability after descent',r'''The notes conclude \(\sigma_T\in L^1_{\mathrm{loc}}\Rightarrow T\in L^1_{\mathrm{loc}}\), then translate a central \(a\) to the identity and refer to special techniques in three Harish-Chandra papers.''',r'''On the image of a surjective submersion, local product coordinates show that a distribution is locally integrable if its pullback is locally integrable. Since \(\varphi^*T=dg\otimes\sigma_T\), local integrability of \(\sigma_T\) gives that of \(T\) near the chosen semisimple orbit. Noncentral descent reduces dimension; central translation, exponential comparison, and the nilpotent analysis complete the regularity theorem.''',r'''The statement is local on the covered image. This induction step does not supply the omitted nilpotent proof or identify exactly which three papers the shorthand counts.''',fate=r'''The completed regularity proof predates the lecture: \citet[Introduction; Theorem~1]{harishchandra1965algebra}.''',refs=['harishchandra1965algebra'],literal='correct with missing hypotheses',match='partial')
correction('P000196','first displayed map','C_c^infty(M) -> C_c^infty(M)','C_c^infty(M) -> C_c^infty(N)','The scan faithfully repeats M; the immediately following variable y, integral over N, and product example fix the target.','both','faithful_error')
correction('P000196','explicit sigma_T formula','beta(a^{-1}z^{-1}xz) for beta defined on Xi','Use phi_!(gamma tensor beta); the displayed expression is not defined for general x,z.','The scan contains the explicit objection “Она не имеет смысла”; the domain mismatch verifies it independently.','both','faithful_error')
correction('P000197','finite-codimension central ideal','the ideal generated by the image of Z(g) has finite codimension','The ideal generated by the image of the finite-codimensional annihilating ideal J has finite codimension in Z(z).','The diagram includes ideals under the centers. Taken literally the whole-center assertion is vacuous because 1 is in its image.','both','ambiguity')
